#!/usr/bin/env node
/**
 * Read-only survey of what a schema cutover would hit in a database that has data.
 *
 * An empty database accepts every schema change, so a cutover rehearsed on one
 * proves nothing about the data that actually exists. Two kinds of change fail
 * only when rows are present:
 *
 *   - A unique index added over columns that already hold duplicates.
 *   - A NOT NULL column added with no database-level default, against a table
 *     that has rows. Prisma's `@default(uuid())` is generated by the client, so
 *     it leaves no DEFAULT behind and cannot fill existing rows.
 *
 * Both halt the cutover mid-flight, one at a time, which is the worst place to
 * discover them. This reads the target database and reports every such blocker
 * at once, so the backfill work can be scoped before a window is booked.
 *
 * The statement list comes from `prisma migrate diff` rather than from reading
 * the schema here: Prisma's own answer about what it would apply is the one that
 * matters, and it stays correct as the schema changes.
 *
 * WHERE THIS MUST BE RUN FROM. It surveys the database exactly as it stands, so
 * the answer is only the cutover's answer at the point `db push` would run: that
 * is *after* the pre-schema data migrations, which is step 3 of
 * `docs/runbooks/operation-automation-cutover.md`. Run it before those
 * migrations and it reports work they already do — `v0.1.31/001` empties the ABC
 * evaluation and grade-history tables, so every NOT NULL column added to them
 * looks like a blocker while the rows are still there. To scope backfill work
 * ahead of a window, restore a copy, apply the pre-schema phase, then run this.
 *
 * Usage:
 *   DATABASE_URL=<target> node scripts/check-cutover-data-blockers.mjs
 *   DATABASE_URL=<target> node scripts/check-cutover-data-blockers.mjs --json
 *
 * Writes nothing. Every statement it issues is a SELECT.
 * Exit 0 when the cutover is clear, 1 when something would block it, 2 on error.
 */
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { resolve } from 'node:path';
import pg from 'pg';

const asJson = process.argv.includes('--json');
const url = process.env.DATABASE_URL;
// Importing this module for its parsers must not require a database, so the
// survey only runs when the file is the entrypoint.
const isEntrypoint = process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1]);

function plannedStatements() {
  const out = execFileSync(
    'npx',
    ['prisma', 'migrate', 'diff', '--from-config-datasource', '--to-schema=prisma', '--script'],
    {
      encoding: 'utf8',
      maxBuffer: 64 * 1024 * 1024,
      env: { ...process.env, DATABASE_URL: url },
    },
  );
  return out;
}

/** `CREATE UNIQUE INDEX "name" ON "table"("a", "b");` — partial indexes carry a WHERE. */
export function uniqueIndexes(sql) {
  const found = [];
  const pattern = /CREATE UNIQUE INDEX\s+"([^"]+)"\s+ON\s+"([^"]+)"\s*\(([^)]*)\)([^;]*);/g;
  for (const match of sql.matchAll(pattern)) {
    const [, name, table, columnList, tail] = match;
    const columns = [...columnList.matchAll(/"([^"]+)"/g)].map((column) => column[1]);
    if (!columns.length) continue;
    found.push({ name, table, columns, where: tail.trim() || null });
  }
  return found;
}

/**
 * `ALTER TABLE "t" ADD COLUMN "c" TYPE NOT NULL` — including the multi-statement
 * form where one ALTER TABLE carries several ADD COLUMN clauses. A clause with
 * its own DEFAULT is fine: the database can fill existing rows itself.
 */
export function notNullAdditions(sql) {
  const found = [];
  for (const statement of sql.split(';')) {
    const table = statement.match(/ALTER TABLE\s+"([^"]+)"/);
    if (!table) continue;
    for (const clause of statement.matchAll(/ADD COLUMN\s+"([^"]+)"\s+([^,\n]*)/g)) {
      const [, column, rest] = clause;
      if (!/\bNOT NULL\b/i.test(rest)) continue;
      if (/\bDEFAULT\b/i.test(rest)) continue;
      found.push({ table: table[1], column });
    }
  }
  return found;
}

/**
 * Values PostgreSQL assigns to rows that predate an ADD COLUMN. A nullable
 * column without a database default starts as NULL. A database DEFAULT is
 * applied by PostgreSQL. A required column without a default cannot be
 * represented here because the separate NOT NULL check must block it first.
 */
export function columnAdditions(sql) {
  const found = [];
  for (const statement of sql.split(';')) {
    const table = statement.match(/ALTER TABLE\s+"([^"]+)"/);
    if (!table) continue;
    for (const clause of statement.matchAll(/ADD COLUMN\s+"([^"]+)"\s+([^,\n]*)/g)) {
      const [, column, rest] = clause;
      const defaultValue = rest.match(/\bDEFAULT\s+(.+?)(?:\s+NOT NULL)?\s*$/i)?.[1]?.trim();
      found.push({
        table: table[1],
        column,
        initialSql: defaultValue ?? (/\bNOT NULL\b/i.test(rest) ? null : 'NULL'),
      });
    }
  }
  return found;
}

export function predicateWithInitialValues(where, table, additions) {
  let resolved = where;
  const replaced = [];
  const tableAdditions = additions
    .filter((addition) => addition.table === table && addition.initialSql !== null)
    .sort((left, right) => left.column.localeCompare(right.column));

  for (const addition of tableAdditions) {
    const escaped = addition.column.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const identifier = new RegExp(`"${escaped}"|\\b${escaped}\\b`, 'g');
    if (!identifier.test(resolved)) continue;
    identifier.lastIndex = 0;
    resolved = resolved.replace(identifier, addition.initialSql);
    replaced.push(addition.column);
  }

  return { where: resolved, replaced };
}

export function surveyExitCode(blockers, pending) {
  return blockers.length > 0 || pending.length > 0 ? 1 : 0;
}

const client = new pg.Client({ connectionString: url });

async function existingColumns(tables) {
  if (!tables.length) return new Map();
  const { rows } = await client.query(
    `SELECT table_name, column_name FROM information_schema.columns
     WHERE table_schema = current_schema() AND table_name = ANY($1::text[])`,
    [tables],
  );
  const byTable = new Map();
  for (const row of rows) {
    if (!byTable.has(row.table_name)) byTable.set(row.table_name, new Set());
    byTable.get(row.table_name).add(row.column_name);
  }
  return byTable;
}

async function rowCount(table) {
  const { rows } = await client.query(`SELECT count(*)::bigint AS n FROM ${ident(table)}`);
  return Number(rows[0].n);
}

/** Identifiers come from Prisma's own DDL, and are quoted rather than interpolated raw. */
function ident(name) {
  return `"${name.replace(/"/g, '""')}"`;
}

async function duplicateGroups({ table, columns, where }) {
  const cols = columns.map(ident).join(', ');
  // A unique index ignores rows where any indexed column is NULL, so those rows
  // cannot collide and must not be counted as duplicates.
  const notNull = columns.map((column) => `${ident(column)} IS NOT NULL`).join(' AND ');
  const filter = where ? `${notNull} AND (${where.replace(/^WHERE\s+/i, '')})` : notNull;
  const { rows } = await client.query(
    `SELECT count(*)::bigint AS groups, COALESCE(sum(n), 0)::bigint AS rows FROM (
       SELECT count(*) AS n FROM ${ident(table)} WHERE ${filter}
       GROUP BY ${cols} HAVING count(*) > 1
     ) duplicates`,
  );
  return { groups: Number(rows[0].groups), rows: Number(rows[0].rows) };
}

async function main() {
  const sql = plannedStatements();
  const indexes = uniqueIndexes(sql);
  const additions = notNullAdditions(sql);
  const plannedColumnAdditions = columnAdditions(sql);
  await client.connect();
  const columnsByTable = await existingColumns([
    ...new Set([...indexes.map((index) => index.table), ...additions.map((add) => add.table)]),
  ]);

  const blockers = [];
  const pending = [];
  const clear = [];

  for (const index of indexes) {
    const present = columnsByTable.get(index.table);
    if (!present) {
      // The table arrives with the schema, so it starts empty.
      clear.push({ kind: 'unique', ...index, note: 'new table' });
      continue;
    }
    const missing = index.columns.filter((column) => !present.has(column));
    if (missing.length) {
      const rows = await rowCount(index.table);
      if (rows === 0) {
        clear.push({ kind: 'unique', ...index, note: 'table empty' });
        continue;
      }
      const initialValues = missing.map(
        (column) =>
          plannedColumnAdditions.find(
            (addition) => addition.table === index.table && addition.column === column,
          )?.initialSql,
      );
      // PostgreSQL unique indexes do not compare rows when any indexed column
      // is NULL. A newly added nullable column therefore cannot collide for the
      // rows that predate this schema application.
      if (initialValues.includes('NULL')) {
        clear.push({
          kind: 'unique',
          ...index,
          note: 'new indexed column is NULL for existing rows',
        });
        continue;
      }
      pending.push({ kind: 'unique', ...index, missing });
      continue;
    }
    let duplicates;
    try {
      const predicate = index.where
        ? predicateWithInitialValues(index.where, index.table, plannedColumnAdditions)
        : { where: null, replaced: [] };
      duplicates = await duplicateGroups({ ...index, where: predicate.where });
    } catch (error) {
      // 42703 undefined_column: a partial index's WHERE clause can name a column
      // this cutover also adds, which the indexed-column check above cannot see.
      // Same situation as a missing indexed column, so report it the same way.
      if (error.code !== '42703') throw error;
      pending.push({
        kind: 'unique',
        ...index,
        missing: ['(in WHERE clause)'],
      });
      continue;
    }
    if (duplicates.groups > 0) blockers.push({ kind: 'unique', ...index, ...duplicates });
    else clear.push({ kind: 'unique', ...index });
  }

  for (const addition of additions) {
    const present = columnsByTable.get(addition.table);
    if (!present) {
      clear.push({ kind: 'not-null', ...addition, note: 'new table' });
      continue;
    }
    if (present.has(addition.column)) {
      clear.push({ kind: 'not-null', ...addition, note: 'already present' });
      continue;
    }
    const rows = await rowCount(addition.table);
    if (rows > 0) blockers.push({ kind: 'not-null', ...addition, rows });
    else clear.push({ kind: 'not-null', ...addition, note: 'table empty' });
  }

  await client.end();

  if (asJson) {
    console.log(JSON.stringify({ blockers, pending, clear: clear.length }, null, 2));
  } else {
    const line = (text) => console.log(text);
    line(
      `\nCutover data survey — ${indexes.length} unique index(es), ${additions.length} NOT NULL column add(s)`,
    );
    // Said before the findings, because reading them from the wrong point in the
    // runbook is what turns this report into noise.
    line("Measured against this database as it stands now. That is the cutover's");
    line('answer only after the pre-schema migrations have run — before them, work');
    line('they already do reads here as a blocker.\n');
    if (blockers.length) {
      line(`BLOCKERS (${blockers.length}) — the cutover stops here:\n`);
      for (const blocker of blockers) {
        line(
          blocker.kind === 'unique'
            ? `  unique   ${blocker.table}(${blocker.columns.join(', ')})\n           ${blocker.groups} duplicate group(s) across ${blocker.rows} row(s) — ${blocker.name}`
            : `  not-null ${blocker.table}.${blocker.column}\n           ${blocker.rows} existing row(s) and no database default to fill them`,
        );
      }
      line('');
    }
    if (pending.length) {
      line(
        `NEEDS A BACKFILL DECISION (${pending.length}) — a new column, so collisions depend on how it is filled:\n`,
      );
      for (const item of pending) {
        line(
          `  unique   ${item.table}(${item.columns.join(', ')})  [new: ${item.missing.join(', ')}]`,
        );
      }
      line('');
    }
    line(`Clear: ${clear.length}`);
    line(
      surveyExitCode(blockers, pending)
        ? '\nFAIL: resolve every blocker and pending decision before booking a cutover window.\n'
        : '\nPASS: nothing in this database blocks the cutover.\n',
    );
  }

  process.exit(surveyExitCode(blockers, pending));
}

if (isEntrypoint) {
  if (!url) {
    console.error('DATABASE_URL is required (the database to survey).');
    process.exit(2);
  }
  main().catch(async (error) => {
    await client.end().catch(() => {});
    console.error(error.message);
    process.exit(2);
  });
}
